from typing import TYPE_CHECKING, Annotated
from fastapi import FastAPI, Depends
import inspect

app = FastAPI()

if TYPE_CHECKING:
    class User:
        pass

def get_user() -> "User":
    return "user"

@app.get("/")
def read_root(user: Annotated["User", Depends(get_user)]):
    return {"user": user}

from fastapi.dependencies.utils import get_typed_signature

